import{_ as t,o,c as s,a3 as a}from"./chunks/framework.qCVWde4n.js";const u=JSON.parse('{"title":"The browser","description":"","frontmatter":{},"headers":[],"relativePath":"browser.md","filePath":"browser.md"}'),n={name:"browser.md"};function r(i,e,h,d,c,l){return o(),s("div",null,[...e[0]||(e[0]=[a(`<h1 id="the-browser" tabindex="-1">The browser <a class="header-anchor" href="#the-browser" aria-label="Permalink to &quot;The browser&quot;">​</a></h1><p>The agent has one browser tool and two browsers to run it in: Chromium through Playwright on the computer the server runs on, and the phone&#39;s own WebView inside the nanoMuse app. The tool is the same either way — the same actions, the same numbered elements on the page, the same pictures in the chat, the same take-over — so a skill written against one works on the other, and a task can move from the desk to the phone without changing a line.</p><p>Where the browser sits in the order of things: the agent reaches a service through its API, MCP server or command-line tool first; then through a <strong>logged-in <code>fetch</code></strong> (a request that carries the browser&#39;s cookies, no page rendered); then through the browser page itself; and only last through the screen of an app on the phone (<a href="./gui">gui.md</a>). The browser is rung two and three of that ladder.</p><h2 id="two-backends" tabindex="-1">Two backends <a class="header-anchor" href="#two-backends" aria-label="Permalink to &quot;Two backends&quot;">​</a></h2><table tabindex="0"><thead><tr><th></th><th><code>playwright</code></th><th><code>device</code></th></tr></thead><tbody><tr><td>Runs</td><td>on the server, headless Chromium</td><td>in the nanoMuse app on the phone, an offscreen WebView</td></tr><tr><td>Needs</td><td><code>pip install &quot;nanomuse[browser]&quot; &amp;&amp; playwright install chromium</code> (or the <code>-browser</code> Docker image)</td><td>the app connected — either flavour; the local build always has it</td></tr><tr><td>Logins live in</td><td><code>&lt;workspace&gt;/browser-profile/</code> — a persistent profile, so a login survives a restart</td><td>the app&#39;s WebView cookie store, on the phone</td></tr><tr><td>Take over</td><td>from the browser card: tap the picture to click, type, press Enter</td><td>the same WebView slides up in the app — no reload, same cookies, your fingers on the real page</td></tr><tr><td>Sites see</td><td>Chrome on Linux (or the profile&#39;s user agent)</td><td>Android WebView (or the profile&#39;s user agent)</td></tr></tbody></table><p><code>backend = &quot;auto&quot;</code> (the default) uses the phone when a nanoMuse app with a browser is connected and Playwright otherwise. On the phone&#39;s local build there is no Chromium — PRoot cannot start one — so the WebView is the browser, always.</p><div class="language-toml vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">toml</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">[</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">browser</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">]</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">enabled    = </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">true</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">backend    = </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;auto&quot;</span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">     # auto | playwright | device</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">profile    = </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;&quot;</span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">         # mobile | desktop | &quot;&quot; (the backend&#39;s own: mobile on the phone, desktop on a computer)</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">headless   = </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">true</span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">       # Playwright only</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">timeout_ms = </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">30000</span></span></code></pre></div><p><code>NANOMUSE_BROWSER_ENABLED=1</code> switches the tool on; <code>NANOMUSE_BROWSER_BACKEND</code> picks the backend. On the phone (<code>NANOMUSE_DEVICE=android</code>) the tool is on by default.</p><h2 id="what-the-agent-can-do" tabindex="-1">What the agent can do <a class="header-anchor" href="#what-the-agent-can-do" aria-label="Permalink to &quot;What the agent can do&quot;">​</a></h2><p>The tool&#39;s actions, identical on both backends:</p><table tabindex="0"><thead><tr><th>Action</th><th>What it does</th></tr></thead><tbody><tr><td><code>navigate url</code></td><td>open a page; the reply lists the interactive elements on it, numbered</td></tr><tr><td><code>extract</code></td><td>the page&#39;s text (the first several thousand characters)</td></tr><tr><td><code>click n</code></td><td>click element <code>n</code> from the last listing (by its centre — what a finger would do)</td></tr><tr><td><code>type n text</code></td><td>fill element <code>n</code>, with the page&#39;s own input events so React and Vue forms notice</td></tr><tr><td><code>key key</code></td><td>press Enter, Tab, Escape …</td></tr><tr><td><code>scroll dy</code></td><td>scroll by pixels, negative for up</td></tr><tr><td><code>back</code></td><td>one step back in history</td></tr><tr><td><code>wait [seconds]</code></td><td>a pause of up to 15 s for a page that is still drawing itself (a single-page app after <code>load</code>), then the page state</td></tr><tr><td><code>screenshot</code></td><td>a fresh picture for the chat card</td></tr><tr><td><code>fetch url [method] [body]</code></td><td>an HTTP request with the browser&#39;s cookies, no page rendered — an order list as JSON, an <code>.ics</code> behind a login, a form post</td></tr><tr><td><code>profile name</code></td><td>present as <code>mobile</code> (412×915, a phone&#39;s user agent) or <code>desktop</code> (1280×900), or a custom user agent and size</td></tr><tr><td><code>close</code></td><td>close the page; the profile and its cookies stay</td></tr></tbody></table><p>Every action that changes the page sends a frame to the chat: a JPEG of the page, its title and URL, and a caption of what just happened (&quot;Clicked &#39;Sign in&#39;&quot;). Frames are the size of the profile&#39;s viewport in CSS pixels, so a point on the picture is the same point on the page — the take-over relies on that. They stay in memory on the server for the session; the last dozen per chat.</p><p>From a script inside the sandbox on the phone the same tool is <code>nanomuse-browser &lt;action&gt; …</code> (<a href="./local-runtime#the-python-side-on-a-phone">local-runtime.md</a>): <code>nanomuse-browser fetch https://example.com/api/orders</code> is rung two from the shell, under the same Sentinel.</p><h2 id="logging-in" tabindex="-1">Logging in <a class="header-anchor" href="#logging-in" aria-label="Permalink to &quot;Logging in&quot;">​</a></h2><p>A page that wants a login is the user&#39;s job, not the model&#39;s. The agent stops at the form and hands the page over (<code>browser</code> → <code>hand_over</code>, with the reason: <em>sign in to 12306</em>, <em>type the code from the SMS</em>, <em>solve the CAPTCHA</em>, <em>confirm the payment</em>); the user does it and presses <strong>Done</strong>; the agent continues with the page as it is. The browser card in the chat is where that happens, and the same card appears when the user takes over first:</p><ul><li><strong>On the server&#39;s Chromium</strong>: <em>Take over</em> on the card (or the agent&#39;s hand-over), then tap the picture to click, scroll, go back, type into the focused field, press Enter, or open a URL; <strong>Done</strong> returns the page. The frame is the page; the taps are mapped onto it; the picture refreshes every second while you have it.</li><li><strong>On the phone</strong>: <em>Take over</em> slides the real WebView up as a sheet in the app — not a picture of it. Sign in with the phone&#39;s keyboard, its autofill and its password manager, and tap <strong>Done</strong>. The view goes back offscreen and the agent is told the page was handed back; its next look shows what you left.</li></ul><p>While the page is yours — a <em>hold</em> — every browser action of that conversation waits; the agent waits up to ten minutes for Done, then carries on with what it sees and says you did not come back. The chat, the live stage, the capsule and the browser viewer all show the same <em>Your turn — &lt;reason&gt; — Done</em> card. Over the API: <code>POST /api/browser/{thread}/control</code> with <code>take_over</code> / <code>handed_back</code>, or <code>POST /api/holds</code> and <code>POST /api/holds/{id}/done</code>; <code>GET /api/state</code> lists the open holds.</p><p>Passwords go to the website, never through the model: what the model sees is the frame after you are done. The agent asks in words (<code>ask_user</code>) only for things it needs to know — which account, which date — never for a password or a code.</p><p>Cookies persist. On the server the Playwright profile is a real Chromium profile directory; on the phone the WebView&#39;s cookie store is flushed to disk after every navigation and <code>fetch</code>. Session cookies — the kind without an expiry, which a browser drops when it closes — do not survive a server restart on either side, so a site that uses only those asks again after <code>nanomuse serve</code> restarts; most sites set a longer &quot;remember me&quot; cookie once you tick the box.</p><h3 id="what-does-not-work-and-why" tabindex="-1">What does not work, and why <a class="header-anchor" href="#what-does-not-work-and-why" aria-label="Permalink to &quot;What does not work, and why&quot;">​</a></h3><ul><li><strong>Google accounts cannot sign in inside a WebView.</strong> Google refuses embedded sign-in (<code>disallowed_useragent</code>) for good reasons. The take-over sheet has an arrow that opens the same URL in the system browser — but a login made there stays in Chrome, not in nanoMuse&#39;s WebView. For Google services use the API path (a calendar&#39;s private <code>.ics</code> link, an app password for mail) instead of the browser; on the server&#39;s Chromium a Google login works but may be challenged as &quot;not secure&quot;.</li><li><strong>A QR code cannot be scanned on the same phone.</strong> Sites that log in by &quot;scan with our app&quot; (微信, 支付宝, 淘宝 …) show the code where the camera would need to be. On the phone&#39;s browser this is a dead end; on the server&#39;s Chromium you scan the frame in the chat with the phone — which is the one case where the server&#39;s browser is the easier one.</li><li><strong>Passkeys are not portable.</strong> A passkey created in the phone&#39;s Chrome belongs to that browser&#39;s credential store; the WebView does not see it, and a headless Chromium on a server has none. Password-and-code logins work everywhere.</li><li><strong>Downloads</strong> land in the workspace: <code>&lt;workspace&gt;/downloads/</code> on the server (Playwright) and in the local build on the phone (where the agent can read them); in the connect build, whose agent is on the computer, they go to the phone&#39;s Downloads folder.</li><li>One tab. A link that opens a new window opens in the same page instead.</li></ul><h2 id="how-the-phone-s-browser-works" tabindex="-1">How the phone&#39;s browser works <a class="header-anchor" href="#how-the-phone-s-browser-works" aria-label="Permalink to &quot;How the phone&#39;s browser works&quot;">​</a></h2><p>The WebView must think it is on screen — a hidden WebView throttles <code>requestAnimationFrame</code> to nothing and timers to one a second, and many pages never finish loading. The app therefore gives it a screen: a private <strong>virtual display</strong> (an <code>ImageReader</code> surface, seen by nobody) with a <code>Presentation</code> window on it holding the WebView. Chromium composes frames into that surface at full speed whether or not the app is on screen; the latest frame is what a <code>screenshot</code> returns, so video, canvas and WebGL come out as they are. Measured on the emulator with the app in the background: 60 rAF/s, <code>setInterval(10 ms)</code> at 100/s, <code>visibilityState = visible</code>. On a device that refuses a virtual display the WebView falls back to being measured and drawn by hand.</p><p>Taps are injected as touch events at the element&#39;s centre, typing goes through the page&#39;s own setters plus <code>input</code> / <code>change</code> events (so frameworks notice), Enter presses the key. The one page is a singleton; the take-over moves that same <code>WebView</code> object into the sheet&#39;s container and back, so nothing reloads. Cookies, including third-party ones, are on; <code>CookieManager.flush()</code> runs after every load and <code>fetch</code>.</p><h3 id="the-protocol" tabindex="-1">The protocol <a class="header-anchor" href="#the-protocol" aria-label="Permalink to &quot;The protocol&quot;">​</a></h3><p>The phone announces <code>{&quot;kind&quot;: &quot;device&quot;, …, &quot;browser&quot;: true}</code> when its socket opens; the server then sends <code>device_request</code> messages with <code>op: &quot;browser&quot;</code> and answers arrive as <code>device_result</code> with the same <code>id</code>. The ops, from <code>nanomuse/tools/browser_backends.py</code> (<code>DeviceBackend</code>), implemented in <code>android/…/browser/DeviceBrowser.kt</code>:</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>open      {user_agent, width, height, mobile}  → {url, title, width, height, …}</span></span>
<span class="line"><span>navigate  {url}                                → {url, title, …}</span></span>
<span class="line"><span>evaluate  {js, arg}                            → {value, encoded: &quot;json&quot;}   runs (js)(arg)</span></span>
<span class="line"><span>tap       {x, y}                               → {}                          CSS px of the viewport</span></span>
<span class="line"><span>type      {text}                               → {}                          into the focused element</span></span>
<span class="line"><span>key       {key}                                → {}</span></span>
<span class="line"><span>scroll    {dy}                                 → {}</span></span>
<span class="line"><span>back      {}                                   → {url, title, …}</span></span>
<span class="line"><span>settle    {timeout_ms}                         → {}</span></span>
<span class="line"><span>screenshot {quality}                           → {jpeg: base64, width, height}</span></span>
<span class="line"><span>state     {}                                   → {url, title, width, height, loading, user_control, host}</span></span>
<span class="line"><span>fetch     {url, method, headers, body}         → {status, headers, body, url}   with the WebView&#39;s cookies</span></span>
<span class="line"><span>profile   {user_agent, width, height, mobile}  → {}</span></span>
<span class="line"><span>close     {}                                   → {}</span></span></code></pre></div><p>An unknown op or a failure comes back as <code>{&quot;ok&quot;: false, &quot;error&quot;: &quot;…&quot;}</code> — a message the model can read. Another app that wants to lend its browser to a nanoMuse server implements these fourteen ops and the hello.</p><h2 id="testing-it" tabindex="-1">Testing it <a class="header-anchor" href="#testing-it" aria-label="Permalink to &quot;Testing it&quot;">​</a></h2><p><code>tests/test_browser.py</code> runs the tool against a fake backend (parity of the two, frames, the take-over hand-back) and, when Playwright and Chromium are installed, against the real one (the persistent profile, cookies across a restart, <code>fetch</code> with a session, the profile switch). The phone side has been driven end to end on an Android 13 emulator: every op above, cookies set by a page arriving in <code>fetch</code>, typing landing in the right field, the take-over sheet showing the same live page and the hand-back reaching the server. What still wants a real phone: vendors&#39; battery managers pausing the app&#39;s process, and the virtual display on Android 8–10.</p>`,30)])])}const g=t(n,[["render",r]]);export{u as __pageData,g as default};
